/**
 * What to call this forge out loud. These are 14px silhouettes, so every mark
 * ends up inside the accessible name of the link that wraps it — Codeberg's
 * mountain is not a shape anyone is obliged to recognise.
 *
 * "other" is a forge nobody named in the data, so the git glyph is all we can
 * honestly claim; saying "Git" would assert more than the entry does.
 */
export const forgeName = (
	host: Forge,
	t: (key: "repo.forgeOther") => string,
): string => (host === "other" ? t("repo.forgeOther") : FORGE_MARK[host].name);

/** Decorative on purpose: the link around it carries the name. */
export function ForgeIcon({
	host,
	className = "size-3.5 shrink-0",
}: {
	host: Forge;
	className?: string;
}) {
	return (
		<svg
			viewBox="0 0 24 24"
			fill="currentColor"
			aria-hidden="true"
			className={className}
		>
			<path d={FORGE_MARK[host].d} />
		</svg>
	);
}

/**
 * `docker compose up` works on this one. Decorative on purpose: a lone whale is
 * a riddle, so every caller puts the word next to it.
 */
export function ComposeIcon({
	className = "size-3 shrink-0",
}: {
	className?: string;
}) {
	return (
		<svg
			viewBox="0 0 24 24"
			fill="currentColor"
			aria-hidden="true"
			className={className}
		>
			<path d={COMPOSE_D} />
		</svg>
	);
}

/**
 * How a mark should read, without depending on colour to say it.
 *
 * These are compliance-adjacent claims — "SSO is included", "the data can sit in
 * the EU" — so the tone only ever reinforces a word that is already there.
 * Nothing here is ever rendered as a bare glyph.
 *
 *   plain   — a fact with no cost attached
 *   warn    — this one costs the reader something: an SSO tax, a paywalled half
 *   bad     — this one disqualifies the entry for the reason someone came here
 *   unknown — nobody checked. Never a tick and never a cross.
 *   vary    — the products citing this project do not agree; see `Project.factsVary`
 */
export type FactTone = "plain" | "warn" | "bad" | "unknown" | "vary";

/**
 * One fact, ready to render: a glyph, the i18n key of the word that goes beside
 * it, and how it reads.
 *
 * `label` is a plain string rather than the frontend's `Key` union because this
 * module is imported by the components that own the translator, not the other
 * way round — the caller narrows it.
 */
export type FactMark = { Icon: LucideIcon; label: string; tone: FactTone };

/** Fields whose citations disagree render as this instead of as a guess. */
const varied = (label: string): FactMark => ({
	Icon: CircleHelp,
	label,
	tone: "vary",
});

/**
 * Can you actually run it? A "no" here is not a shade of grey: it is the entry
 * failing the one question the catalogue exists to ask.
 */
export const selfHostMark = (
	selfHostable: boolean,
	vary?: boolean,
): FactMark =>
	vary
		? varied("facts.varies.selfHost")
		: selfHostable
			? { Icon: Server, label: "facts.selfHost", tone: "plain" }
			: { Icon: ServerOff, label: "facts.noSelfHost", tone: "bad" };

/**
 * Where the data may legally sit — the GDPR question, asked the only way this
 * dataset can answer it honestly.
 *
 * One shield for all four values, with the word carrying the distinction: an EU
 * shield and a US shield that differ only in fill would be a colour-only signal,
 * and neither is a shape anyone recognises. "unknown" gets the question mark and
 * is dropped by callers that have no room for it, never turned into a "no".
 */
export const residencyMark = (
	residency: Facts["dataResidency"],
	vary?: boolean,
): FactMark =>
	vary
		? varied("facts.varies.residency")
		: residency === "unknown"
			? {
					Icon: ShieldQuestionMark,
					label: "facts.residency.unknown",
					tone: "unknown",
				}
			: {
					Icon: residency === "self" ? ShieldCheck : Shield,
					label: `facts.residency.${residency}`,
					// A US-only host is a real cost to a reader who came here for GDPR;
					// an EU option and your own server are not.
					tone: residency === "us-only" ? "warn" : "plain",
				};

/**
 * The SSO tax. `null` is 387 of 871 projects, so it is the common case rather
 * than an edge: it renders as an explicit "not checked", never as a cross.
 */
export const ssoMark = (ssoInFree: boolean | null, vary?: boolean): FactMark =>
	vary
		? varied("facts.varies.sso")
		: ssoInFree === null
			? { Icon: CircleHelp, label: "facts.ssoUnknown", tone: "unknown" }
			: ssoInFree
				? { Icon: KeyRound, label: "facts.sso", tone: "plain" }
				: { Icon: KeyRound, label: "facts.ssoPaid", tone: "warn" };

/** The licence, which is a legal fact and wears the legal glyph. */
export const LicenceIcon = Scale;

/**
 * The one the owner singled out: self-hosted versus cloud, and whether the
 * self-hostable build is the whole product or a demo of it.
 *
 * `major` is the claim that most often makes "open source alternative" false in
 * practice, so it is the only fact here that gets its own block rather than a
 * tag in the row.
 */
export const openCoreMark = (
	openCore: Facts["openCore"],
	vary?: boolean,
): FactMark =>
	vary
		? varied("facts.varies.openCore")
		: {
				Icon: PackageOpen,
				label: `facts.openCore.${openCore}`,
				tone:
					openCore === "none" ? "plain" : openCore === "minor" ? "warn" : "bad",
			};
